export function requireAdmin(handler: (req: Req) => Promise<unknown>) {
  return async (req: Req) => {
    if (req.user.role !== "admin") throw new Error("forbidden");
    return handler(req);
  };
}

export interface Req {
  user: { id: string; role: string };
}

